import SwiftUI
struct ParlaysView:View {
 @EnvironmentObject var store:AppStore;@State private var collapsed=Set<String>();@State private var minimumLegs=2;@State private var maximumDecimal=13.0;@State private var allPrices=true;@State private var included=Set<String>()
 var allTickets:[ParlayTicket]{store.groups.flatMap(\.tickets)};var maxLegs:Int{max(2,allTickets.map{$0.legs.count}.max() ?? 2)};var maxOdds:Double{max(2,allTickets.map(\.decimal).max() ?? 13)}
 func shown(_ t:ParlayTicket)->Bool{t.legs.count>=minimumLegs&&(allPrices||t.decimal<=maximumDecimal)&&(included.isEmpty||t.legs.allSatisfy{included.contains($0.athleteId)})}
 var body:some View{ScrollView{VStack(alignment:.leading,spacing:18){Text("Built around your reads.").font(.largeTitle.bold());if store.groups.isEmpty{ContentUnavailableView("Your next shortlist",systemImage:"square.stack",description:Text("Pick two or more fighters, then create parlays."));Button("Pick fighters"){store.tab=0}}else{DisclosureGroup("Fighters, odds & legs"){VStack(alignment:.leading){Stepper("At least \(minimumLegs) legs",value:$minimumLegs,in:2...maxLegs);Toggle("All quoted prices",isOn:$allPrices);if !allPrices{Text("Up to \(americanOdds(maximumDecimal))");Slider(value:$maximumDecimal,in:2...maxOdds)};ForEach(store.payload()?.picks ?? [],id:\.athleteId){p in Toggle(p.fighter ?? p.athleteId,isOn:Binding(get:{included.contains(p.athleteId)},set:{if $0{included.insert(p.athleteId)}else{included.remove(p.athleteId)}}))};Text("No fighters checked means all your selections.").font(.caption).foregroundStyle(.secondary)}}.padding().background(.white.opacity(0.04),in:RoundedRectangle(cornerRadius:14));ForEach(store.groups){g in VStack(alignment:.leading,spacing:12){Button{withAnimation{if collapsed.contains(g.id){collapsed.remove(g.id)}else{collapsed.insert(g.id)}}}label:{HStack{Text(g.title).font(.title2.bold());Spacer();Image(systemName:collapsed.contains(g.id) ? "chevron.down":"chevron.up")}}.buttonStyle(.plain);if !collapsed.contains(g.id){ForEach(g.tickets.filter(shown)){t in TicketView(ticket:t)};Text(g.note ?? "").font(.caption2).foregroundStyle(.secondary)}}};if let payload=store.payload(){NavigationLink("Your stats-backed shortlist"){ResearchLabView(payload:payload).navigationTitle("Fight research").navigationBarTitleDisplayMode(.inline)}.font(.subheadline)};Text("Displayed prices are calculated estimates. The sportsbook decides which legs can be combined and the final price. No wager is placed here.").font(.caption).foregroundStyle(.secondary)}}.padding()}.navigationTitle("Parlays").onChange(of:store.groups.count){_,_ in maximumDecimal=maxOdds}}
}
struct TicketView:View { @EnvironmentObject var store:AppStore;var ticket:ParlayTicket
 var body:some View{VStack(alignment:.leading,spacing:12){HStack{Text("\(ticket.legs.count) LEGS").font(.caption.bold()).foregroundStyle(.secondary);Spacer();Text(americanOdds(ticket.decimal)).font(.title2.monospacedDigit().bold()).foregroundStyle(Color.accentColor)};ForEach(Array(ticket.legs.enumerated()),id:\.offset){_,l in HStack(alignment:.top){VStack(alignment:.leading){Text(l.label).font(.subheadline.bold());Text(l.market).font(.caption).foregroundStyle(.secondary);if l.outside==true{Text("NOT YOUR PICK").font(.caption2.bold()).foregroundStyle(.orange)}};Spacer();Text(americanOdds(l.decimal)).font(.caption.monospacedDigit())}};Text(ticket.reason).font(.caption);Text(ticket.risk).font(.caption2).foregroundStyle(.secondary);Button("Save ticket"){store.run{try await store.saveTicket(ticket)}}.buttonStyle(.bordered)}.padding().background(.white.opacity(0.05),in:RoundedRectangle(cornerRadius:16))}}
